import { arrange, type SynthEvent, type TrackNote } from "./arrange";
import { CATEGORIES, SONG_DEFS, type CategoryDef, type CategoryId, type SongDef } from "./songDefs";
import { midiToName, midiToSolfege } from "./notation";
import { mulberry32 } from "../lib/random";

export { CATEGORIES };
export type { CategoryDef, CategoryId };

/** A playable level. Built-in tracks are generated by code only (Web Audio), never from audio files. */
export interface Track {
  id: string;
  title: string;
  titleFa: string;
  artist: string;
  bpm: number;
  duration: number;
  difficulty: number;
  palette: string;
  kind: "builtin" | "uploaded";
  lead?: string;
  fx?: { d: number; fb: number; wet: number; damp: number };
  notes: TrackNote[];
  synth?: SynthEvent[];
  peaks: number[];
  // ---- extra info for built-in songs ----
  category?: CategoryId;
  blurb?: string;
  key?: string;
  meter?: string;
  /** illustration id (see SongArt) */
  art?: string;
  /** distinct pitches used by every lane, low → high */
  laneRanges?: { lane: number; from: string; to: string; fromFa: string; toFa: string }[];
  [extra: string]: unknown;
}

function makePeaks(notes: TrackNote[], duration: number, seed: number): number[] {
  const bins = new Array(64).fill(0);
  for (const n of notes) {
    const i = Math.min(63, Math.floor((n.t / duration) * 64));
    const v = n.accent ? 1 : 0.68;
    for (let k = -2; k <= 2; k++) {
      const j = i + k;
      if (j >= 0 && j < 64) bins[j] = Math.max(bins[j], v * (1 - Math.abs(k) * 0.24));
    }
  }
  const rnd = mulberry32(seed);
  return bins.map((h, i) => {
    const s = 0.5 + 0.5 * Math.sin((i / 64) * Math.PI);
    return Math.max(0.08, Math.min(1, (h + rnd() * 0.22) * (0.55 + s * 0.7)));
  });
}

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function buildTrack(def: SongDef): Track & { warnings: string[] } {
  const arr = arrange({
    melody: def.melody,
    chords: def.chords,
    bpm: def.bpm,
    beatsPerBar: def.beatsPerBar,
    pickup: def.pickup,
    repeat: def.repeat,
    acc: def.acc,
    lead: def.lead,
  });

  const laneRanges: Track["laneRanges"] = [];
  for (let lane = 0; lane < 4; lane++) {
    const ms = arr.notes.filter((n) => n.lane === lane).map((n) => n.midi);
    if (!ms.length) continue;
    const lo = Math.min(...ms);
    const hi = Math.max(...ms);
    laneRanges.push({ lane, from: midiToName(lo), to: midiToName(hi), fromFa: midiToSolfege(lo), toFa: midiToSolfege(hi) });
  }

  const d = def.acc.delay ?? [0.75, 0.3, 0.2, 2600];
  const spb = 60 / def.bpm;
  return {
    id: def.id,
    title: def.title,
    titleFa: def.titleFa,
    artist: def.artist,
    bpm: def.bpm,
    duration: arr.duration,
    difficulty: def.difficulty,
    palette: def.palette,
    kind: "builtin",
    lead: def.lead,
    fx: { d: Math.min(0.95, spb * d[0]), fb: d[1], wet: d[2], damp: d[3] },
    notes: arr.notes,
    synth: arr.synth,
    peaks: makePeaks(arr.notes, arr.duration, hash(def.id)),
    category: def.category,
    blurb: def.blurb,
    key: def.key,
    meter: def.meter,
    art: def.id,
    laneRanges,
    warnings: arr.warnings,
  };
}

export const BUILTIN_TRACKS: Track[] = SONG_DEFS.map((def) => {
  const { warnings, ...track } = buildTrack(def);
  if (warnings.length && (import.meta as any).env?.DEV) console.warn(`[song:${def.id}]`, warnings);
  return track as Track;
});

export const DEFAULT_TRACK: Track = BUILTIN_TRACKS[0];

export function tracksByCategory(id: CategoryId): Track[] {
  return BUILTIN_TRACKS.filter((t) => t.category === id);
}

export function categoryOf(track: { category?: string }): CategoryDef | undefined {
  return CATEGORIES.find((c) => c.id === track.category);
}
